// Helpers shared by the dashboard services: the request context (settings, today, now), date
// ranges, the section 7.10 day summary, each person's day (holidays and leave, CONTRACT 25), and
// view-model pieces used on more than one screen.
import {
  clockToMinutes,
  dayjs,
  formatClock,
  formatClockShort,
  formatDay,
  formatDayMonthShort,
  formatHours,
  formatTime,
  formatTimeAmPm,
  isoWeekday,
  localToUtc,
  monthOf,
  monthRange,
  now,
  weekRange,
  workDate,
} from '@/lib/time';
import { plural } from '@/lib/text';
import { attendance } from '@/modules/attendance';
import { settings } from '@/modules/settings';

/** Settings, time zone, the current moment and today's company date for one request. */
export async function loadContext() {
  const all = await settings.getAll();
  const tz = all.timezone;
  const at = now();
  return { settings: all, tz, now: at, today: workDate(tz, at) };
}

/**
 * Whether the viewer may see Admins' attendance (check-ins, breaks, screen time). Company rule:
 * only another Admin may, so for a PM or HR Admins are left out of every attendance view, count
 * and detail page. No viewer is a system read (tests, jobs), which sees everyone, as in the
 * attendance module.
 * @param {{ role?: string } | null | undefined} viewer the signed-in person
 */
export function showsAdmins(viewer) {
  return !viewer || viewer.role === 'admin';
}

/**
 * Today's report time (settings.reportReminderAt, company time): before it a report that isn't
 * submitted yet is still due, from it on it is missing.
 * @returns {{ at: Date, label: string, before: boolean }} label '6:30 PM'
 */
export function reportDue(ctx) {
  const clock = ctx.settings.reportReminderAt;
  const at = localToUtc(ctx.today, clock, ctx.tz).toDate();
  return { at, label: formatClock(clock), before: ctx.now.isBefore(at) };
}

/** 'Wednesday, 30 September, 6:52 PM' (the dashboards' top bar subtitle). */
export function nowSubtitle(ctx) {
  return `${formatDay(ctx.today)}, ${formatTimeAmPm(ctx.now, ctx.tz)}`;
}

/**
 * Week (Monday to today) or month (the 1st to today) ending today.
 * @param {'week'|'month'} key
 * @param {string} today
 */
export function periodFor(key, today) {
  if (key === 'month') return { key: 'month', from: monthRange(monthOf(today)).from, to: today };
  return { key: 'week', from: weekRange(today).from, to: today };
}

/** Percentage 0-100 with one decimal, 0 when there is nothing to divide by. */
export function percent(part, whole) {
  if (!whole || whole <= 0) return 0;
  return Math.min(100, Math.max(0, Math.round((part / whole) * 1000) / 10));
}

/** '1 person' / '26 people' */
export function people(count) {
  return `${count} ${plural(count, 'person', 'people')}`;
}

// Presences of someone off without a check-in (CONTRACT 25): leave, a holiday, a day off.
const OFF_PRESENCES = new Set(['on_leave', 'holiday', 'day_off']);

/** True for a presence that means "off today" (leave, a holiday or a day off, no check-in). */
export function isOff(presence) {
  return OFF_PRESENCES.has(presence);
}

/**
 * The calendar the dashboards read (CONTRACT 25): holidays and leave of a date range, never the
 * leave type, pay or note (no leaveDetail) and never "WFH approved" (no WFH read), so a PM's
 * payload can't carry them.
 * @param {{ from: string, to: string }} range
 */
export function loadDashboardCalendar({ from, to }) {
  return attendance.loadCalendar({ from, to, withWfh: false });
}

/**
 * The company holiday on a date when it falls on a working weekday (`{ name }`), else null: a
 * holiday on a day the company doesn't work changes nothing.
 */
export function holidayOn(calendar, date, workingDays) {
  const holiday = calendar.holidayOn(date);
  return holiday && workingDays.includes(isoWeekday(date)) ? { name: holiday.name } : null;
}

/**
 * listTrackedPeopleDay rows with each person's day on `date` and their presence at `ctx.now`
 * (attendance.presenceOf: first-half leave reads on_leave until the split, today only), and
 * `lateMinutes` as the effective late (0 on a day without a late mark). `day` stays on the
 * server: board rows copy only what they show.
 * @param {object[]} rows
 * @param {{ calendar: object, date: string,
 *   ctx: { now: import('dayjs').Dayjs, tz: string } }} input
 * @returns {object[]} rows plus { day, presence, lateMinutes }
 */
export function withPresence(rows, { calendar, date, ctx }) {
  return rows.map((row) => {
    const day = calendar.dayFor(row, date);
    const checkIn = row.attendanceId
      ? {
          location: row.location,
          officeVerified: Boolean(row.officeVerified),
          lateMinutes: Number(row.lateMinutes ?? 0),
        }
      : null;
    return {
      ...row,
      day,
      presence: attendance.presenceOf({ day, row: checkIn, at: ctx.now, tz: ctx.tz }),
      lateMinutes: attendance.effectiveLateMinutes({ row: checkIn, day }),
    };
  });
}

/**
 * The day's numbers as build guide section 7.10 counts them, from the rows of
 * listTrackedPeopleDay (active people with tracks_attendance = 1 who had joined by that day),
 * with each person's presence (withPresence, CONTRACT 25): checked in = rows with attendance;
 * WFH = of those, location wfh; late = of those, effective late minutes > 0, averaged over late
 * rows only; not checked in = presence not_checked_in only (expected now); off = on leave, a
 * holiday or a day off without a check-in; reports submitted = submitted reports among the
 * people who checked in. Rows without a presence count as 1.09 did (no row = not checked in).
 */
export function summarizeDay(rows) {
  const presenceOf = (row) => row.presence ?? (row.attendanceId ? 'office' : 'not_checked_in');
  const present = rows.filter((row) => row.attendanceId);
  const wfh = present.filter((row) => row.location === 'wfh').length;
  const late = present.filter((row) => Number(row.lateMinutes) > 0);
  const lateTotal = late.reduce((sum, row) => sum + Number(row.lateMinutes), 0);
  const submitted = present.filter((row) => row.reportStatus === 'submitted').length;
  return {
    tracked: rows.length,
    checkedIn: present.length,
    office: present.length - wfh,
    wfh,
    notCheckedIn: rows.filter((row) => presenceOf(row) === 'not_checked_in').length,
    off: rows.filter((row) => isOff(presenceOf(row))).length,
    late: {
      count: late.length,
      averageMinutes: late.length ? Math.round(lateTotal / late.length) : 0,
    },
    reports: { submitted, of: present.length, missing: present.length - submitted },
  };
}

/** The "Reports submitted" number card: '21' 'of 24, due 6:30'. */
export function reportsKpi(summary, ctx) {
  return {
    key: 'reports',
    label: 'Reports submitted',
    value: String(summary.reports.submitted),
    sub: `of ${summary.reports.of}, due ${formatClockShort(ctx.settings.reportReminderAt)}`,
    percent: percent(summary.reports.submitted, summary.reports.of),
    color: 'green',
  };
}

/**
 * The "Checked in" / "In today" number card: '24' 'of 26 people', or 'of 26 people, 2 off' when
 * some are off (CONTRACT 25). The bar counts over the people expected (tracked less those off),
 * as Attendance's Present card does.
 */
export function checkedInKpi(summary, label) {
  const off = summary.off ?? 0;
  return {
    key: 'checkedIn',
    label,
    value: String(summary.checkedIn),
    sub: off > 0 ? `of ${people(summary.tracked)}, ${off} off` : `of ${people(summary.tracked)}`,
    percent: percent(summary.checkedIn, summary.tracked - off),
    color: 'primary',
  };
}

const MAX_BARS = 8;

/**
 * Hours-by-project rows as HBarList rows, largest first. More than eight projects show the top
 * seven and one "N more projects" row. Hours from a pending project request carry "(requested)".
 * Hours are logged in quarter hours, so they show exactly ('5.25h', never a rounded '5.3h').
 */
export function hoursBars(rows) {
  const shown = rows.length > MAX_BARS ? rows.slice(0, MAX_BARS - 1) : rows;
  const rest = rows.slice(shown.length);
  const bars = shown.map((row) => ({
    key: row.projectId ? `p${row.projectId}` : `r${row.requestId}`,
    label: row.projectId ? row.name : `${row.name} (requested)`,
    value: row.minutes,
    display: formatHours(row.minutes),
    color: row.projectId ? (row.color ?? 'blue') : 'muted',
  }));
  if (rest.length) {
    const minutes = rest.reduce((sum, row) => sum + row.minutes, 0);
    bars.push({
      key: 'more',
      label: `${rest.length} more projects`,
      value: minutes,
      display: formatHours(minutes),
      color: 'muted',
    });
  }
  return bars;
}

/** Total minutes of hours-by-project rows. */
export function totalMinutes(rows) {
  return rows.reduce((sum, row) => sum + row.minutes, 0);
}

/** '11:05' when marked today, otherwise '29 Sep'. */
function markedWhen(at, ctx) {
  if (!at) return null;
  return workDate(ctx.tz, at) === ctx.today
    ? formatTime(at, ctx.tz)
    : formatDayMonthShort(workDate(ctx.tz, at));
}

function onIt(count) {
  if (!count) return 'nobody on it yet';
  return `${people(count)} on it`;
}

/**
 * Urgent projects for the dashboards. `by: 'members'` gives 'Marked 11:05, 2 people on it'
 * (Team dashboard); `by: 'marker'` gives 'Marked 11:05 by [PM name]' (Company overview).
 */
export function urgentItems(rows, ctx, by = 'members') {
  return rows.map((row) => {
    const when = markedWhen(row.urgentMarkedAt, ctx);
    const marked = when ? `Marked ${when}` : 'Marked urgent';
    const memberCount = Number(row.memberCount ?? 0);
    const meta =
      by === 'marker'
        ? row.urgentMarkedByName
          ? `${marked} by ${row.urgentMarkedByName}`
          : marked
        : `${marked}, ${onIt(memberCount)}`;
    return {
      id: row.id,
      name: row.name,
      color: row.color,
      note: row.urgentNote ?? '',
      markedAt: isoOrNull(row.urgentMarkedAt),
      markedByName: row.urgentMarkedByName ?? null,
      memberCount,
      meta,
    };
  });
}

/** Minutes of the working day from settings (office start to end), at least one hour. */
export function officeDayMinutes(all) {
  return Math.max(60, clockToMinutes(all.officeEnd) - clockToMinutes(all.officeStart));
}

/** A DATETIME value as an ISO string (serialisable for client components and the API). */
export function isoOrNull(value) {
  return value ? dayjs(value).toISOString() : null;
}
